-- Funciones operativas que bypasean RLS (SECURITY DEFINER) para health/metrics.\n-- Solo lectura agregada; no exponen filas de tenant.\n\nCREATE OR REPLACE FUNCTION ops_outbox_dlq_count()\nRETURNS bigint\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT count(*) FROM projection_outbox WHERE status = 'DEAD_LETTERED';\n$$;\n\nCREATE OR REPLACE FUNCTION ops_outbox_pending_count()\nRETURNS bigint\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT count(*) FROM projection_outbox WHERE status = 'PENDING';\n$$;\n\nCREATE OR REPLACE FUNCTION ops_outbox_stuck_count()\nRETURNS bigint\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT count(*) FROM projection_outbox\n   WHERE status IN ('PENDING','PROCESSING')\n     AND created_at < now() - interval '5 minutes';\n$$;\n\nGRANT EXECUTE ON FUNCTION ops_outbox_dlq_count() TO app_user;\nGRANT EXECUTE ON FUNCTION ops_outbox_pending_count() TO app_user;\nGRANT EXECUTE ON FUNCTION ops_outbox_stuck_count() TO app_user;